SELECT COUNT(DISTINCT TRIM(LOWER(`from`))) AS distinct_senders FROM enron_emailinfo WHERE `from` IS NOT NULL AND TRIM(`from`) != ''
SELECT COUNT(DISTINCT id) AS total_emails FROM enron_emailinfo
SELECT id, messageid, `from` FROM enron_emailinfo WHERE subject IS NULL OR TRIM(subject) = '' ORDER BY id ASC
SELECT COUNT(DISTINCT id) AS reply_count FROM enron_emailinfo WHERE TRIM(subject) LIKE 'Re:%' OR TRIM(subject) LIKE 'RE:%'
SELECT COUNT(DISTINCT id) AS phillip_count FROM enron_emailinfo WHERE TRIM(LOWER(`from`)) = 'phillip.allen@enron.com'
SELECT mailbox, COUNT(DISTINCT id) AS email_count FROM enron_email GROUP BY mailbox ORDER BY email_count DESC LIMIT 10
SELECT COUNT(DISTINCT e.id) AS sent_count FROM enron_email e WHERE e.mailbox = 'sent'
SELECT COUNT(DISTINCT id) AS california_count FROM enron_emailinfo WHERE body LIKE '%California%'
SELECT id, source_file_id, source_name FROM enron_source ORDER BY id ASC LIMIT 10
SELECT DISTINCT mailbox FROM enron_email WHERE mailbox IS NOT NULL AND TRIM(mailbox) != '' ORDER BY mailbox ASC
SELECT `date`, subject, `from` FROM enron_emailinfo WHERE `date` IS NOT NULL AND TRIM(`date`) != '' ORDER BY STR_TO_DATE(SUBSTRING_INDEX(`date`, ' ', 5), '%a, %d %b %Y') DESC LIMIT 10
SELECT COUNT(DISTINCT id) AS count_2001 FROM enron_emailinfo WHERE `date` LIKE '%2001%'
SELECT SUM(CASE WHEN xfrom IS NOT NULL AND TRIM(xfrom) != '' THEN 1 ELSE 0 END) AS xfrom_nonempty_count, SUM(CASE WHEN xto IS NOT NULL AND TRIM(xto) != '' THEN 1 ELSE 0 END) AS xto_nonempty_count FROM enron_emailorig
SELECT DISTINCT people FROM enron_email WHERE people IS NOT NULL AND TRIM(people) != '' ORDER BY people
SELECT COUNT(DISTINCT mailbox) AS campbell_mailboxes FROM enron_email WHERE people = 'campbell-l' AND mailbox IS NOT NULL AND TRIM(mailbox) != ''
SELECT MAX(cnt) AS max_mail_count FROM (SELECT mailbox, COUNT(DISTINCT id) AS cnt FROM enron_email GROUP BY mailbox) t
SELECT COUNT(DISTINCT id) AS meeting_count FROM enron_emailinfo WHERE subject LIKE '%meeting%'
SELECT TRIM(LOWER(`from`)) AS sender, COUNT(DISTINCT id) AS cnt FROM enron_emailinfo WHERE `from` IS NOT NULL AND TRIM(`from`) != '' GROUP BY sender HAVING cnt > 100 ORDER BY cnt DESC, sender ASC
SELECT TRIM(xfrom) AS xfrom_display, COUNT(DISTINCT id) AS cnt FROM enron_emailinfo WHERE xfrom IS NOT NULL AND TRIM(xfrom) != '' GROUP BY xfrom_display ORDER BY cnt DESC, xfrom_display ASC LIMIT 10
SELECT e.id, e.nnn, ei.subject, ei.`from` FROM enron_email e JOIN enron_emailinfo ei ON e.id = ei.id WHERE e.people = 'campbell-l' AND e.mailbox = 'all_documents' ORDER BY e.nnn DESC, e.id DESC LIMIT 10; Medium (m01 - m20)
SELECT e.people, e.mailbox, COUNT(DISTINCT e.id) AS email_count FROM enron_email e GROUP BY e.people, e.mailbox ORDER BY email_count DESC
SELECT et.`to`, COUNT(DISTINCT et.id) AS cnt FROM enron_emailto et JOIN enron_emailinfo ei ON et.id = ei.id WHERE TRIM(LOWER(ei.`from`)) = 'phillip.allen@enron.com' GROUP BY et.`to` ORDER BY cnt DESC LIMIT 10
SELECT `from`, COUNT(DISTINCT id) AS cnt FROM enron_emailinfo WHERE body LIKE '%California%' GROUP BY `from` ORDER BY cnt DESC LIMIT 5
SELECT xorigin, COUNT(DISTINCT xfolder) AS folder_count FROM enron_source WHERE xorigin IS NOT NULL AND TRIM(xorigin) != '' AND xfolder IS NOT NULL AND TRIM(xfolder) != '' GROUP BY xorigin ORDER BY folder_count DESC, xorigin ASC
SELECT sender, avg_recipients FROM ( SELECT TRIM(LOWER(ei.`from`)) AS sender, AVG(COALESCE(rc.recipient_count, 0)) AS avg_recipients FROM enron_emailinfo ei LEFT JOIN ( SELECT id, COUNT(nthto) AS recipient_count FROM enron_emailto GROUP BY id ) rc ON ei.id = rc.id WHERE ei.`from` IS NOT NULL AND TRIM(ei.`from`) != '' GROUP BY sender ) sub WHERE avg_recipients > 3 ORDER BY avg_recipients DESC
SELECT ROUND( (SELECT COUNT(DISTINCT id) FROM enron_email WHERE mailbox = 'sent') * 100.0 / (SELECT COUNT(DISTINCT id) FROM enron_email), 2) AS sent_percentage
SELECT et.`to`, COUNT(DISTINCT et.id) AS cnt FROM enron_emailto et GROUP BY et.`to` ORDER BY cnt DESC LIMIT 1
SELECT LPAD(MONTH(STR_TO_DATE(SUBSTRING_INDEX(`date`, ' ', 5), '%a, %d %b %Y')), 2, '0') AS month_num, COUNT(DISTINCT id) AS cnt FROM enron_emailinfo WHERE `date` LIKE '%2001%' GROUP BY month_num ORDER BY month_num ASC
SELECT e.mailbox, COUNT(DISTINCT e.id) AS cnt FROM enron_email e WHERE e.people = 'allen-p' GROUP BY e.mailbox ORDER BY cnt DESC
SELECT eo.`from` AS original_sender, COUNT(DISTINCT eo.id) AS reply_count FROM enron_emailinfo ei JOIN enron_emailorig eo ON ei.id = eo.id WHERE TRIM(LOWER(ei.`from`)) = 'phillip.allen@enron.com' AND (ei.subject LIKE 'Re:%' OR ei.subject LIKE 'RE:%') GROUP BY eo.`from` ORDER BY reply_count DESC LIMIT 5
SELECT ei.id, ei.subject, COALESCE((SELECT MAX(nthto) FROM enron_emailto et WHERE et.id = ei.id), 0) AS max_nthto, COALESCE((SELECT MAX(nthxto) FROM enron_emailxto xt WHERE xt.id = ei.id), 0) AS max_nthxto FROM enron_emailinfo ei ORDER BY GREATEST( COALESCE((SELECT MAX(nthto) FROM enron_emailto et WHERE et.id = ei.id), 0), COALESCE((SELECT MAX(nthxto) FROM enron_emailxto xt WHERE xt.id = ei.id), 0) ) DESC, ei.id ASC LIMIT 10
SELECT et.`to`, COUNT(DISTINCT et.id) AS cnt FROM enron_emailto et JOIN enron_emailinfo ei ON et.id = ei.id WHERE TRIM(LOWER(ei.`from`)) = 'enron.announcements@enron.com' GROUP BY et.`to` ORDER BY cnt DESC LIMIT 5
SELECT xfilename, COUNT(DISTINCT id) AS cnt FROM enron_source WHERE xfilename IS NOT NULL AND TRIM(xfilename) != '' GROUP BY xfilename ORDER BY cnt DESC, xfilename ASC LIMIT 5
SELECT ei.id, COALESCE((SELECT COUNT(DISTINCT et.`to`) FROM enron_emailto et WHERE et.id = ei.id), 0) AS to_count, COALESCE((SELECT COUNT(DISTINCT TRIM(xt.xto)) FROM enron_emailxto xt WHERE xt.id = ei.id AND xt.xto IS NOT NULL AND TRIM(xt.xto) != ''), 0) AS xto_count, ABS(COALESCE((SELECT COUNT(DISTINCT et.`to`) FROM enron_emailto et WHERE et.id = ei.id), 0) - COALESCE((SELECT COUNT(DISTINCT TRIM(xt.xto)) FROM enron_emailxto xt WHERE xt.id = ei.id AND xt.xto IS NOT NULL AND TRIM(xt.xto) != ''), 0)) AS abs_diff, LEFT(ei.`to`, 200) AS to_preview, LEFT(ei.xto, 200) AS xto_preview FROM enron_emailinfo ei ORDER BY abs_diff DESC, ei.id ASC LIMIT 10
SELECT TRIM(LOWER(ei.`from`)) AS sender, COUNT(DISTINCT TRIM(LOWER(et.`to`))) AS unique_recipients FROM enron_emailinfo ei JOIN enron_emailto et ON ei.id = et.id WHERE ei.`from` IS NOT NULL AND TRIM(ei.`from`) != '' AND et.`to` IS NOT NULL AND TRIM(et.`to`) != '' GROUP BY sender ORDER BY unique_recipients DESC, sender ASC LIMIT 1
SELECT e.people, COUNT(DISTINCT e.id) AS cnt FROM enron_email e WHERE e.mailbox = 'deleted_items' GROUP BY e.people ORDER BY cnt DESC
SELECT ei.id, ei.subject, eo.subject AS orig_subject, eo.`from` AS orig_from, eo.`to` AS orig_to, eo.xfrom AS orig_xfrom, eo.xto AS orig_xto FROM enron_emailinfo ei JOIN enron_emailorig eo ON ei.id = eo.id WHERE TRIM(ei.subject) LIKE 'Re:%' AND eo.nth = 1 ORDER BY ei.id ASC
SELECT et.`to`, COUNT(DISTINCT et.id) AS cnt FROM enron_emailto et JOIN enron_emailinfo ei ON et.id = ei.id WHERE ei.`date` LIKE '%2001%' AND ei.`date` LIKE '%Oct%' GROUP BY et.`to` ORDER BY cnt DESC, et.`to` ASC LIMIT 5
SELECT COUNT(DISTINCT e.id) AS cnt FROM enron_email e JOIN enron_emailinfo ei ON e.id = ei.id WHERE TRIM(LOWER(ei.`from`)) = 'larry.campbell@enron.com' AND e.mailbox = 'inbox'
SELECT xorigin, COUNT(DISTINCT id) AS cnt FROM enron_source GROUP BY xorigin ORDER BY cnt DESC LIMIT 5; Hard (h01 - h10)
SELECT COUNT(DISTINCT TRIM(LOWER(ei.`from`))) AS both_count FROM enron_emailinfo ei WHERE ei.`from` IS NOT NULL AND TRIM(ei.`from`) != '' AND TRIM(LOWER(ei.`from`)) IN ( SELECT TRIM(LOWER(et.`to`)) FROM enron_emailto et WHERE et.`to` IS NOT NULL AND TRIM(et.`to`) != '' )
SELECT TRIM(LOWER(ei.`from`)) AS sender, COUNT(DISTINCT ei.id) AS sent_count FROM enron_emailinfo ei WHERE ei.`from` IS NOT NULL AND TRIM(ei.`from`) != '' AND TRIM(LOWER(ei.`from`)) NOT IN ( SELECT TRIM(LOWER(et.`to`)) FROM enron_emailto et WHERE et.`to` IS NOT NULL AND TRIM(et.`to`) != '' ) GROUP BY sender ORDER BY sent_count DESC, sender ASC
SELECT subject, COUNT(DISTINCT id) AS reply_count FROM enron_emailinfo WHERE subject LIKE 'Re:%' OR subject LIKE 'RE:%' GROUP BY subject ORDER BY reply_count DESC LIMIT 3
SELECT people, sender, cnt, rn FROM ( SELECT e.people, TRIM(LOWER(ei.`from`)) AS sender, COUNT(DISTINCT e.id) AS cnt, ROW_NUMBER() OVER (PARTITION BY e.people ORDER BY COUNT(DISTINCT e.id) DESC, TRIM(LOWER(ei.`from`)) ASC) AS rn FROM enron_email e JOIN enron_emailinfo ei ON e.id = ei.id WHERE e.people IS NOT NULL AND TRIM(e.people) != '' AND ei.`from` IS NOT NULL AND TRIM(ei.`from`) != '' GROUP BY e.people, sender ) t WHERE rn <= 3 ORDER BY people ASC, rn ASC
WITH busiest_day AS ( SELECT DATE(STR_TO_DATE(SUBSTRING_INDEX(`date`, ' ', 5), '%a, %d %b %Y')) AS send_date FROM enron_emailinfo WHERE `date` IS NOT NULL AND `date` != '' GROUP BY send_date ORDER BY COUNT(DISTINCT id) DESC LIMIT 1 ) SELECT TRIM(LOWER(`from`)) AS sender, COUNT(DISTINCT id) AS cnt FROM enron_emailinfo WHERE `date` IS NOT NULL AND `date` != '' AND DATE(STR_TO_DATE(SUBSTRING_INDEX(`date`, ' ', 5), '%a, %d %b %Y')) = (SELECT send_date FROM busiest_day) AND `from` IS NOT NULL AND TRIM(`from`) != '' GROUP BY sender ORDER BY cnt DESC LIMIT 5
SELECT type, cnt, ROUND(cnt * 100.0 / ( SELECT COUNT(DISTINCT id) FROM enron_emailinfo WHERE `from` IS NOT NULL AND TRIM(`from`) != '' ), 2) AS pct FROM ( SELECT CASE WHEN TRIM(LOWER(`from`)) LIKE '%@enron.com' THEN 'internal' ELSE 'external' END AS type, COUNT(DISTINCT id) AS cnt FROM enron_emailinfo WHERE `from` IS NOT NULL AND TRIM(`from`) != '' GROUP BY CASE WHEN TRIM(LOWER(`from`)) LIKE '%@enron.com' THEN 'internal' ELSE 'external' END ) t ORDER BY type ASC
SELECT email, COUNT(DISTINCT people) AS people_count FROM ( SELECT DISTINCT TRIM(LOWER(ei.`from`)) AS email, e.people FROM enron_emailinfo ei JOIN enron_email e ON ei.id = e.id WHERE e.people IN ('campbell-l','allen-p','badeer-r') AND ei.`from` IS NOT NULL AND TRIM(ei.`from`) != '' UNION SELECT DISTINCT TRIM(LOWER(et.`to`)) AS email, e.people FROM enron_emailto et JOIN enron_email e ON et.id = e.id WHERE e.people IN ('campbell-l','allen-p','badeer-r') AND et.`to` IS NOT NULL AND TRIM(et.`to`) != '' ) t GROUP BY email HAVING people_count >= 2 ORDER BY people_count DESC, email ASC
SELECT et.`to`, SUM(CASE WHEN ei.`from` = 'larry.campbell@enron.com' THEN 1 ELSE 0 END) AS campbell_count, SUM(CASE WHEN ei.`from` = 'phillip.allen@enron.com' THEN 1 ELSE 0 END) AS allen_count FROM enron_emailto et JOIN enron_emailinfo ei ON et.id = ei.id WHERE ei.`from` IN ('larry.campbell@enron.com', 'phillip.allen@enron.com') GROUP BY et.`to` HAVING campbell_count > 0 AND allen_count > 0 ORDER BY campbell_count DESC, allen_count DESC
SELECT ROUND(AVG(orig_count), 4) AS avg_orig_count, MAX(orig_count) AS max_orig_count, SUM(CASE WHEN orig_count >= 3 THEN 1 ELSE 0 END) AS ge3_count FROM ( SELECT eo.id, COUNT(*) AS orig_count FROM enron_emailorig eo GROUP BY eo.id ) t
SELECT people, mailbox, cnt FROM ( SELECT people, mailbox, COUNT(DISTINCT id) AS cnt, RANK() OVER (PARTITION BY people ORDER BY COUNT(DISTINCT id) DESC) AS rn FROM enron_email GROUP BY people, mailbox ) t WHERE rn = 1 ORDER BY people ASC
